package com.chathighlightplayer;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.events.BeforeMenuRender;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.util.Text;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;


@Slf4j
@PluginDescriptor(
		name = "Chat Highlight Player",
	description = "Highlight players by clicking their names in chat."
)
@SuppressWarnings({"deprecation", "unused"})
public class ChatHighlightPlayerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ChatHighlightPlayerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ChatHighlightPlayerOverlay overlay;

	@Inject
	private ChatHighlightPlayerMinimapOverlay minimapOverlay;

	private String targetPlayerName;
	private long durationSeconds = 10;
	private Color color = Color.pink;

	private long startTime = 0;
	private boolean isActive = false;
	private boolean showLine = true;

	private static final String REPORT = "Report";
	private static final String TRADE = "Accept trade";
	private static final String CONFIG_GROUP = "chathighlightplayer";

	@Subscribe
	public void onGameTick(GameTick event) {
		initiatehighlight();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		overlay.setTrimLines(config.trimHighlightLines());
		overlay.setFadeHighlights(config.fadeHighlights());
		overlay.setFadeDurationMs(config.fadeDurationMs());
		// Apply overlay layer change immediately (remove & re-add to ensure manager picks it up)
		overlayManager.remove(overlay);
		overlay.setLayer(config.overlayAboveWidgets() ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.UNDER_WIDGETS);
		overlayManager.add(overlay);
		// Update minimap overlay fade settings but keep it always above widgets
		minimapOverlay.setFadeHighlights(config.fadeHighlights());
		minimapOverlay.setFadeDurationMs(config.fadeDurationMs());
		initiatehighlight();
	}

	private boolean isHighlightActive()
	{
		if (!isActive)
		{
			return false;
		}

		long currentTime = System.currentTimeMillis();
		long effectiveDuration = Math.max(0, Math.min(durationSeconds, 120)); // enforce max 120s regardless of config
		if (currentTime >= startTime + effectiveDuration * 1000)
		{
			isActive = false;
			return false;
		}

		return true;
	}

	private void initiatehighlight(){
		boolean temporaryHighlightActive = isHighlightActive() && targetPlayerName != null && targetPlayerName.length() > 1;
		if (!temporaryHighlightActive)
		{
			overlay.setHighlightedPlayers(Collections.emptyMap());
			minimapOverlay.setHighlightedPlayers(Collections.emptyMap());
			return;
		}

		Map<Player, HighlightStyle> highlightedPlayers = new LinkedHashMap<>();
		String targetNormalized = targetPlayerName.toLowerCase(Locale.ENGLISH);
		HighlightStyle tempStyle = new HighlightStyle(color, showLine, config.showTemporaryPlayerName(), config.temporaryMenuOption(), config.temporaryHighlightRegularMenuPlayerName(), config.temporaryHideOtherPlayerMenus());
		for (Player player : client.getPlayers()) {
			if (player == null || player.getName() == null) {
				continue;
			}

			if (normalizePlayerName(player.getName()).toLowerCase(Locale.ENGLISH).equals(targetNormalized)) {
				highlightedPlayers.put(player, tempStyle);
			}
		}

		overlay.setHighlightedPlayers(highlightedPlayers);
		minimapOverlay.setHighlightedPlayers(highlightedPlayers);
	}

	private void setHighlightPlayer(String playerName) {
		targetPlayerName = "";
		targetPlayerName = normalizePlayerName(playerName);
		startTime = System.currentTimeMillis();
		isActive = true;
		showLine = config.line();
		// Use selected preset duration (seconds)
		durationSeconds = config.duration().seconds();
		color = config.tagColor();

		// Optionally announce in chat that a player was highlighted
		if (config.announceHighlightInChat()) {
			String cleaned = cleanPlayerName(playerName);
			String hex = colorToHex(config.tagColor()).replace("#", "");
			String nameFormatted = "<col=" + hex + ">" + cleaned + "</col>";
			String msg = "Highlighted: " + nameFormatted;
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
		}

		initiatehighlight();
	}

	private String colorToHex(Color color) {
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}

	private String buildHighlightedPlayerTarget(String rawTarget, Color highlightColor)
	{
		String cleanedTarget = cleanPlayerName(rawTarget);
		String levelSuffix = "";
		int levelIdx = cleanedTarget.indexOf(" (level-");
		if (levelIdx >= 0)
		{
			levelSuffix = cleanedTarget.substring(levelIdx);
			cleanedTarget = cleanedTarget.substring(0, levelIdx);
		}

		String hexColor = colorToHex(highlightColor).replace("#", "");
		if (levelSuffix.isEmpty())
		{
			return "<col=" + hexColor + ">" + cleanedTarget + "</col>";
		}

		return "<col=" + hexColor + ">" + cleanedTarget + "</col><col=ff9040>" + levelSuffix + "</col>";
	}

	private HighlightStyle getMenuHighlightStyle(String playerName)
	{
		if (playerName == null || playerName.length() <= 1)
		{
			return null;
		}

		if (isHighlightActive() && playerName.equalsIgnoreCase(targetPlayerName))
		{
			return new HighlightStyle(color, showLine, config.showTemporaryPlayerName(), config.temporaryMenuOption(), config.temporaryHighlightRegularMenuPlayerName(), config.temporaryHideOtherPlayerMenus());
		}

		return null;
	}

	private boolean shouldSkipMenuOptionHighlight(String configuredMenuOption)
	{
		if (configuredMenuOption == null || configuredMenuOption.trim().isEmpty())
		{
			return true;
		}

		for (String rawConfiguredOption : configuredMenuOption.split(","))
		{
			String cleanConfiguredOption = Text.removeTags(rawConfiguredOption).trim();
			if (!cleanConfiguredOption.isEmpty() && !cleanConfiguredOption.equalsIgnoreCase("none"))
			{
				return false;
			}
		}

		return true;
	}

	private boolean shouldHighlightMenuOption(String menuOption, String configuredMenuOption)
	{
		if (menuOption == null || shouldSkipMenuOptionHighlight(configuredMenuOption))
		{
			return false;
		}

		String cleanMenuOption = Text.removeTags(menuOption).trim();
		for (String rawConfiguredOption : configuredMenuOption.split(","))
		{
			String cleanConfiguredOption = Text.removeTags(rawConfiguredOption).trim();
			if (cleanConfiguredOption.equals("*") || cleanMenuOption.equalsIgnoreCase(cleanConfiguredOption))
			{
				return true;
			}
		}

		return false;
	}

	private void highlightMatchingMenuEntry(MenuEntry menuEntry)
	{
		String optionName = normalizePlayerName(menuEntry.getOption());
		String targetName = normalizePlayerName(menuEntry.getTarget());

		HighlightStyle optionStyle = getMenuHighlightStyle(optionName);
		HighlightStyle targetStyle = getMenuHighlightStyle(targetName);
		boolean isCondensedParent = menuEntry.getSubMenu() != null
			&& menuEntry.getType() == MenuAction.RUNELITE
			&& menuEntry.getOption().isEmpty();
		if (isCondensedParent && optionStyle != null && !shouldSkipMenuOptionHighlight(optionStyle.getMenuOption()))
		{
			String hexColor = colorToHex(optionStyle.getColor()).replace("#", "");
			menuEntry.setOption("<col=" + hexColor + ">" + menuEntry.getOption() + "</col>");
		}
		boolean shouldHighlightPlayerName = targetStyle != null
			&& ((isCondensedParent && config.highlightCondensedPlayerName())
				|| (!isCondensedParent && targetStyle.isHighlightRegularMenuPlayerName()));
		if (shouldHighlightPlayerName)
		{
			menuEntry.setTarget(buildHighlightedPlayerTarget(menuEntry.getTarget(), targetStyle.getColor()));
		}
		if (targetStyle != null && shouldHighlightMenuOption(menuEntry.getOption(), targetStyle.getMenuOption()))
		{
			String hexColor = colorToHex(targetStyle.getColor()).replace("#", "");
			menuEntry.setOption("<col=" + hexColor + ">" + menuEntry.getOption() + "</col>");
		}
	}

	private Set<String> getKnownPlayerNames()
	{
		Set<String> playerNames = new LinkedHashSet<>();
		for (Player player : client.getPlayers())
		{
			if (player != null && player.getName() != null)
			{
				playerNames.add(normalizePlayerName(player.getName()).toLowerCase(Locale.ENGLISH));
			}
		}

		return playerNames;
	}

	private String getMenuEntryPlayerName(MenuEntry menuEntry, Set<String> knownPlayerNames)
	{
		String targetName = normalizePlayerName(menuEntry.getTarget()).toLowerCase(Locale.ENGLISH);
		if (knownPlayerNames.contains(targetName))
		{
			return targetName;
		}

		String optionName = normalizePlayerName(menuEntry.getOption()).toLowerCase(Locale.ENGLISH);
		if (knownPlayerNames.contains(optionName))
		{
			return optionName;
		}

		return null;
	}

	private MenuEntry[] filterMenuEntriesForHighlightedPlayers(MenuEntry[] menuEntries)
	{
		Set<String> knownPlayerNames = getKnownPlayerNames();
		if (knownPlayerNames.isEmpty())
		{
			return menuEntries;
		}

		Set<String> focusedPlayerNames = new LinkedHashSet<>();
		for (MenuEntry menuEntry : menuEntries)
		{
			String playerName = getMenuEntryPlayerName(menuEntry, knownPlayerNames);
			if (playerName == null)
			{
				continue;
			}

			HighlightStyle style = getMenuHighlightStyle(playerName);
			if (style != null && style.isHideOtherPlayerMenus())
			{
				focusedPlayerNames.add(playerName);
			}
		}

		if (focusedPlayerNames.isEmpty())
		{
			return menuEntries;
		}

		List<MenuEntry> filteredEntries = new ArrayList<>(menuEntries.length);
		for (MenuEntry menuEntry : menuEntries)
		{
			String playerName = getMenuEntryPlayerName(menuEntry, knownPlayerNames);
			if (playerName == null || focusedPlayerNames.contains(playerName))
			{
				filteredEntries.add(menuEntry);
			}
		}

		return filteredEntries.toArray(new MenuEntry[0]);
	}

	private void addChatHighlightMenuEntry(String username, String target)
	{
		Color customColor = config.tagColor();
		String hexColor = colorToHex(customColor);
		client.createMenuEntry(1)
				.setOption("<col=" + hexColor.replace("#", "") + ">" + "Highlight Player" + "</col>")
				.setTarget(target)
				.setType(MenuAction.RUNELITE_HIGH_PRIORITY)
				.onClick(e -> setHighlightPlayer(username));
	}

	private boolean isChatboxMessageEntry(int packedWidgetId)
	{
		final int groupId = WidgetUtil.componentToInterface(packedWidgetId);
		final int childId = WidgetUtil.componentToId(packedWidgetId);
		if (groupId != InterfaceID.CHATBOX)
		{
			return false;
		}

		final Widget widget = client.getWidget(groupId, childId);
		if (widget == null)
		{
			return false;
		}

		final Widget parent = widget.getParent();
		if (parent == null || ComponentID.CHATBOX_MESSAGE_LINES != parent.getId())
		{
			return false;
		}

		final int first = WidgetUtil.componentToId(ComponentID.CHATBOX_FIRST_MESSAGE);
		final int dynamicChildId = (childId - first) * 4 + 1;
		return parent.getChild(dynamicChildId) != null;
	}

	private boolean isChatboxReportMenuEntry(MenuEntry menuEntry)
	{
		return REPORT.equals(menuEntry.getOption()) && isChatboxMessageEntry(menuEntry.getParam1());
	}

	private boolean isMenuEntryMissing(String text)
	{
		for (MenuEntry menuEntry : client.getMenu().getMenuEntries())
		{
			if (menuEntry.getOption().contains(text))
			{
				return false;
			}
		}

		return true;
	}

	private void maybeAddChatMenuEntries(String username, String target, boolean includeHighlightEntry)
	{
		if (username.trim().length() <= 1)
		{
			return;
		}

		if (includeHighlightEntry && isMenuEntryMissing("Highlight Player"))
		{
			addChatHighlightMenuEntry(username, target);
		}
	}

	private String cleanPlayerName(String name) {
		if (name == null)
		{
			return "";
		}

		return Text.removeTags(name)
				.replace('\u00A0', ' ')
				.trim();
	}

	private String normalizePlayerName(String name)
	{
		return cleanPlayerName(name)
				.replaceAll("\\s*\\(level-\\d+\\)$", "")
				.trim();
	}

	@Override
	protected void startUp()
	{
		log.info("ChatHighlightPlayerPlugin started!");
		overlay.setTrimLines(config.trimHighlightLines());
		overlay.setFadeHighlights(config.fadeHighlights());
		overlay.setFadeDurationMs(config.fadeDurationMs());
		// Layer controlled by config (default above widgets)
		overlay.setLayer(config.overlayAboveWidgets() ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.UNDER_WIDGETS);
		overlayManager.add(overlay);

		// Minimap overlay should always render above widgets so the dot remains visible
		minimapOverlay.setFadeHighlights(config.fadeHighlights());
		minimapOverlay.setFadeDurationMs(config.fadeDurationMs());
		minimapOverlay.setLayer(OverlayLayer.ABOVE_WIDGETS);
		overlayManager.add(minimapOverlay);
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded entry) {
		highlightMatchingMenuEntry(entry.getMenuEntry());

		if (entry.getType() != MenuAction.CC_OP.getId() && entry.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())
		{
			return;
		}

		if (!isChatboxMessageEntry(entry.getActionParam1()))
		{
			return;
		}

		if (entry.getOption().toLowerCase().contains(TRADE.toLowerCase()) ) {
			String username = cleanPlayerName(entry.getTarget());
			if (isMenuEntryMissing("Highlight Player"))
			{
				Color customColor = config.tagColor();
				String hexColor = colorToHex(customColor);
				client.createMenuEntry(1)
						.setOption("<col=" + hexColor.replace("#", "") + ">" + "Highlight Player" + "</col>")
						.setTarget(entry.getTarget())
						.setType(MenuAction.WIDGET_SECOND_OPTION)
						.onClick(e -> setHighlightPlayer(username));
			}
			return;
		}

		if (entry.getOption().equals(REPORT) && config.showHoverHighlight()) {
			String username = cleanPlayerName(entry.getTarget());
			maybeAddChatMenuEntries(username, entry.getTarget(), true);
		}

	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		for (MenuEntry menuEntry : client.getMenuEntries())
		{
			if (isChatboxReportMenuEntry(menuEntry))
			{
				String username = cleanPlayerName(menuEntry.getTarget());
				if (username.trim().length() > 1)
				{
					maybeAddChatMenuEntries(username, menuEntry.getTarget(), true);
					moveHighlightPlayerEntryToTop();
				}
				break;
			}
		}

		MenuEntry[] menuEntries = filterMenuEntriesForHighlightedPlayers(client.getMenuEntries());
		for (MenuEntry menuEntry : menuEntries)
		{
			highlightMatchingMenuEntry(menuEntry);
		}
		client.setMenuEntries(menuEntries);
	}

	@Subscribe
	public void onBeforeMenuRender(BeforeMenuRender event)
	{
		MenuEntry[] menuEntries = filterMenuEntriesForHighlightedPlayers(client.getMenuEntries());
		for (MenuEntry menuEntry : menuEntries)
		{
			highlightMatchingMenuEntry(menuEntry);
		}
		client.setMenuEntries(menuEntries);
	}

	private void moveHighlightPlayerEntryToTop()
	{
		MenuEntry[] menuEntries = client.getMenuEntries();
		List<MenuEntry> reordered = new ArrayList<>(menuEntries.length);
		MenuEntry highlightEntry = null;

		for (MenuEntry menuEntry : menuEntries)
		{
			if (menuEntry.getOption().contains("Highlight Player"))
			{
				highlightEntry = menuEntry;
				continue;
			}

			reordered.add(menuEntry);
		}

		if (highlightEntry != null)
		{
			reordered.add(highlightEntry);
			client.setMenuEntries(reordered.toArray(new MenuEntry[0]));
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(minimapOverlay);
		log.info("ChatHighlightPlayerPlugin stopped!");
	}

	@Provides
	ChatHighlightPlayerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatHighlightPlayerConfig.class);
	}
}

package com.chathighlightplayer;

import java.awt.Color;

final class HighlightStyle
{
	private final Color color;
	private final boolean showLine;
	private final boolean showName;
	private final String menuOption;
	private final boolean highlightRegularMenuPlayerName;
	private final boolean hideOtherPlayerMenus;

	HighlightStyle(Color color, boolean showLine, boolean showName, String menuOption, boolean highlightRegularMenuPlayerName, boolean hideOtherPlayerMenus)
	{
		this.color = color;
		this.showLine = showLine;
		this.showName = showName;
		this.menuOption = menuOption;
		this.highlightRegularMenuPlayerName = highlightRegularMenuPlayerName;
		this.hideOtherPlayerMenus = hideOtherPlayerMenus;
	}

	Color getColor()
	{
		return color;
	}

	boolean isShowLine()
	{
		return showLine;
	}

	boolean isShowName()
	{
		return showName;
	}

	String getMenuOption()
	{
		return menuOption;
	}

	boolean isHighlightRegularMenuPlayerName()
	{
		return highlightRegularMenuPlayerName;
	}

	boolean isHideOtherPlayerMenus()
	{
		return hideOtherPlayerMenus;
	}
}

package com.chathighlightplayer;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

public class ChatHighlightPlayerMinimapOverlay extends Overlay {
    private static final int DEFAULT_FADE_DURATION_MS = 400;
    private static final int MIN_FADE_DURATION_MS = 100;
    private static final int MAX_FADE_DURATION_MS = 2000;

    private Map<String, RenderedHighlight> highlightedPlayers = Collections.emptyMap();
    private final Map<String, RenderedHighlight> fadingPlayers = new LinkedHashMap<>();
    private boolean fadeHighlights = true;
    private int fadeDurationMs = DEFAULT_FADE_DURATION_MS;

    @Inject
    private Client client;

    @Inject
    private ChatHighlightPlayerConfig config;

    @Inject
    public ChatHighlightPlayerMinimapOverlay() {
        setPosition(OverlayPosition.DYNAMIC);
        // Always render above widgets so minimap dot remains visible regardless of plugin overlay settings
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    void setHighlightedPlayers(Map<Player, HighlightStyle> highlightedPlayers) {
        long now = System.currentTimeMillis();
        Map<String, RenderedHighlight> updatedHighlights = new LinkedHashMap<>();

        for (Map.Entry<Player, HighlightStyle> entry : highlightedPlayers.entrySet()) {
            Player player = entry.getKey();
            if (player == null || player.getName() == null) {
                continue;
            }

            String playerName = normalizePlayerName(player.getName());
            updatedHighlights.put(playerName, new RenderedHighlight(player, entry.getValue()));
            fadingPlayers.remove(playerName);
        }

        if (fadeHighlights) {
            for (Map.Entry<String, RenderedHighlight> entry : this.highlightedPlayers.entrySet()) {
                if (!updatedHighlights.containsKey(entry.getKey()) && !fadingPlayers.containsKey(entry.getKey())) {
                    RenderedHighlight fadingHighlight = entry.getValue();
                    fadingHighlight.startFade(now);
                    fadingPlayers.put(entry.getKey(), fadingHighlight);
                }
            }
        } else {
            fadingPlayers.clear();
        }

        this.highlightedPlayers = updatedHighlights;
    }

    void setFadeHighlights(boolean fadeHighlights) {
        this.fadeHighlights = fadeHighlights;
        if (!fadeHighlights) {
            fadingPlayers.clear();
        }
    }

    void setFadeDurationMs(int fadeDurationMs) {
        this.fadeDurationMs = clamp(fadeDurationMs, MIN_FADE_DURATION_MS, MAX_FADE_DURATION_MS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        long now = System.currentTimeMillis();
        for (RenderedHighlight highlight : highlightedPlayers.values()) {
            renderDot(graphics, highlight.getPlayer(), highlight.getStyle(), 1.0f);
        }

        Iterator<Map.Entry<String, RenderedHighlight>> iterator = fadingPlayers.entrySet().iterator();
        while (iterator.hasNext()) {
            RenderedHighlight highlight = iterator.next().getValue();
            float fadeAlpha = highlight.getFadeAlpha(now, fadeDurationMs);
            if (fadeAlpha <= 0.0f) {
                iterator.remove();
                continue;
            }

            renderDot(graphics, highlight.getPlayer(), highlight.getStyle(), fadeAlpha);
        }
        return null;
    }

    private void renderDot(Graphics2D graphics, Player targetPlayer, HighlightStyle style, float alpha) {
        if (targetPlayer == null) {
            return;
        }

        Composite originalComposite = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

        Color color = style.getColor();
        // Use the player's LocalPoint (includes in-tile movement) so the minimap dot animates smoothly.
        LocalPoint targetLocalPos = null;
        try {
            targetLocalPos = targetPlayer.getLocalLocation();
        } catch (NoSuchMethodError ignored) {
            // Older API builds may not have getLocalLocation(); fall back to world->local conversion
        }
        if (targetLocalPos == null) {
            WorldPoint targetWorldPos = targetPlayer.getWorldLocation();
            targetLocalPos = LocalPoint.fromWorld(client, targetWorldPos);
        }

        if (config.showMinimapDot() && targetLocalPos != null) {
            Point minimapPoint = Perspective.localToMinimap(client, targetLocalPos);
            if (minimapPoint != null) {
                int size = config.minimapDotSize().size();
                int half = size / 2;

                // Outline: subtle filled ring (size+2) with reduced opacity, centers cleanly
                float outlineOpacity = 0.75f;
                int outlineSize = size + 2;
                int outerHalf = outlineSize / 2;

                // Draw outline (filled) with multiplied alpha so fading affects it
                graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha * outlineOpacity));
                graphics.setColor(Color.BLACK);
                graphics.fillOval(minimapPoint.getX() - outerHalf, minimapPoint.getY() - outerHalf, outlineSize, outlineSize);

                // Inner dot: restore base alpha
                graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
                graphics.setColor(color);
                graphics.fillOval(minimapPoint.getX() - half, minimapPoint.getY() - half, size, size);
            }
        }

        graphics.setComposite(originalComposite);
    }

    private int clamp(int value, int min, int max) {
        return Math.max(min, Math.min(max, value));
    }

    private String normalizePlayerName(String name) {
        return name.toLowerCase().trim();
    }

    private static final class RenderedHighlight {
        private final Player player;
        private final HighlightStyle style;
        private long fadeStartTime = -1L;

        private RenderedHighlight(Player player, HighlightStyle style) {
            this.player = player;
            this.style = style;
        }

        private Player getPlayer() {
            return player;
        }

        private HighlightStyle getStyle() {
            return style;
        }

        private void startFade(long now) {
            fadeStartTime = now;
        }

        private float getFadeAlpha(long now, int fadeDurationMs) {
            if (fadeStartTime < 0L) {
                return 1.0f;
            }

            long elapsed = now - fadeStartTime;
            if (elapsed >= fadeDurationMs) {
                return 0.0f;
            }

            return 1.0f - (float) elapsed / fadeDurationMs;
        }
    }
}

package com.chathighlightplayer;

import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Collections;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

public class ChatHighlightPlayerOverlay extends Overlay {
    private static final int DEFAULT_FADE_DURATION_MS = 400;
    private static final int MIN_FADE_DURATION_MS = 100;
    private static final int MAX_FADE_DURATION_MS = 2000;
    private static final int MIN_LINE_START_PADDING = 18;
    private static final int MAX_LINE_START_PADDING = 42;
    private static final int MIN_LINE_END_PADDING = 10;
    private static final int MAX_LINE_END_PADDING = 28;
    private static final double LINE_START_PADDING_RATIO = 0.08d;
    private static final double LINE_END_PADDING_RATIO = 0.05d;
    private Map<String, RenderedHighlight> highlightedPlayers = Collections.emptyMap();
    private final Map<String, RenderedHighlight> fadingPlayers = new LinkedHashMap<>();
    private boolean trimLines = true;
    private boolean fadeHighlights = true;
    private int fadeDurationMs = DEFAULT_FADE_DURATION_MS;

    @Inject
    private Client client;

    @Inject
    private ChatHighlightPlayerConfig config;

    @Inject
    public ChatHighlightPlayerOverlay() {
		setPosition(OverlayPosition.DYNAMIC);
    }

    void setHighlightedPlayers(Map<Player, HighlightStyle> highlightedPlayers) {
        long now = System.currentTimeMillis();
        Map<String, RenderedHighlight> updatedHighlights = new LinkedHashMap<>();

        for (Map.Entry<Player, HighlightStyle> entry : highlightedPlayers.entrySet()) {
            Player player = entry.getKey();
            if (player == null || player.getName() == null) {
                continue;
            }

            String playerName = normalizePlayerName(player.getName());
            updatedHighlights.put(playerName, new RenderedHighlight(player, entry.getValue()));
            fadingPlayers.remove(playerName);
        }

        if (fadeHighlights) {
            for (Map.Entry<String, RenderedHighlight> entry : this.highlightedPlayers.entrySet()) {
                if (!updatedHighlights.containsKey(entry.getKey()) && !fadingPlayers.containsKey(entry.getKey())) {
                    RenderedHighlight fadingHighlight = entry.getValue();
                    fadingHighlight.startFade(now);
                    fadingPlayers.put(entry.getKey(), fadingHighlight);
                }
            }
        } else {
            fadingPlayers.clear();
        }

        this.highlightedPlayers = updatedHighlights;
    }

    void setTrimLines(boolean trimLines) {
        this.trimLines = trimLines;
    }

    void setFadeHighlights(boolean fadeHighlights) {
        this.fadeHighlights = fadeHighlights;
        if (!fadeHighlights) {
            fadingPlayers.clear();
        }
    }

    void setFadeDurationMs(int fadeDurationMs) {
        this.fadeDurationMs = clamp(fadeDurationMs, MIN_FADE_DURATION_MS, MAX_FADE_DURATION_MS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        long now = System.currentTimeMillis();
        for (RenderedHighlight highlight : highlightedPlayers.values()) {
            renderHighlight(graphics, highlight.getPlayer(), highlight.getStyle(), 1.0f);
        }

        Iterator<Map.Entry<String, RenderedHighlight>> iterator = fadingPlayers.entrySet().iterator();
        while (iterator.hasNext()) {
            RenderedHighlight highlight = iterator.next().getValue();
            float fadeAlpha = highlight.getFadeAlpha(now, fadeDurationMs);
            if (fadeAlpha <= 0.0f) {
                iterator.remove();
                continue;
            }

            renderHighlight(graphics, highlight.getPlayer(), highlight.getStyle(), fadeAlpha);
        }
        return null;
    }

    private void renderHighlight(Graphics2D graphics, Player targetPlayer, HighlightStyle style, float alpha) {
        if (targetPlayer == null) {
            return;
        }

        Composite originalComposite = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

        Color color = style.getColor();
        WorldPoint targetWorldPos = targetPlayer.getWorldLocation();
        LocalPoint targetLocalPos = LocalPoint.fromWorld(client, targetWorldPos);

        if (style.isShowLine() && client.getLocalPlayer() != null) {
            WorldPoint myWorldPos = client.getLocalPlayer().getWorldLocation();
            LocalPoint myLocalPos = LocalPoint.fromWorld(client, myWorldPos);

            if (myLocalPos != null && targetLocalPos != null) {
                @SuppressWarnings("deprecation")
                int plane = client.getPlane();
                Point myScreenPos = Perspective.localToCanvas(client, myLocalPos, plane);
                Point targetScreenPos = Perspective.localToCanvas(client, targetLocalPos, plane);

                if (myScreenPos != null && targetScreenPos != null) {
                    graphics.setColor(color);
                    if (trimLines) {
                        drawTrimmedLine(graphics, myScreenPos, targetScreenPos);
                    } else {
                        graphics.drawLine(myScreenPos.getX(), myScreenPos.getY(),
                                targetScreenPos.getX(), targetScreenPos.getY());
                    }
                }
            }
        }


        // Choose render mode: TILE uses existing tile highlight; OUTLINE draws model outline around player
        if (config.highlightMode() == ChatHighlightPlayerConfig.HighlightMode.TILE) {
            OverlayUtil.renderActorOverlay(graphics, targetPlayer, style.isShowName() ? targetPlayer.getName() : "", color);
        } else {
            Shape hull = targetPlayer.getConvexHull();
            if (hull != null) {
                graphics.setColor(color);
                graphics.setStroke(new BasicStroke(2));
                graphics.draw(hull);
            }
            // Optionally draw name above head if requested
            if (style.isShowName()) {
                if (hull != null) {
                    java.awt.Rectangle bounds = hull.getBounds();
                    java.awt.FontMetrics fm = graphics.getFontMetrics();
                    String name = targetPlayer.getName();
                    int textWidth = fm.stringWidth(name);
                    int textX = bounds.x + (bounds.width - textWidth) / 2;
                    int textY = bounds.y - 4; // slightly above the top of the hull
                    // baseline adjustment
                    int baseline = textY - fm.getDescent();
                    graphics.setColor(color);
                    graphics.drawString(name, textX, baseline);
                } else {
                    // fallback to canvas position above the player's tile
                    Point textPoint = Perspective.localToCanvas(client, targetLocalPos, client.getPlane());
                    if (textPoint != null) {
                        graphics.setColor(color);
                        graphics.drawString(targetPlayer.getName(), textPoint.getX(), textPoint.getY() - 20);
                    }
                }
            }
        }

        graphics.setComposite(originalComposite);
    }

    private void drawTrimmedLine(Graphics2D graphics, Point start, Point end) {
        int dx = end.getX() - start.getX();
        int dy = end.getY() - start.getY();
        double length = Math.hypot(dx, dy);
        int startPadding = clamp((int) Math.round(length * LINE_START_PADDING_RATIO), MIN_LINE_START_PADDING, MAX_LINE_START_PADDING);
        int endPadding = clamp((int) Math.round(length * LINE_END_PADDING_RATIO), MIN_LINE_END_PADDING, MAX_LINE_END_PADDING);

        if (length <= startPadding + endPadding) {
            return;
        }

        double unitX = dx / length;
        double unitY = dy / length;

        int trimmedStartX = (int) Math.round(start.getX() + unitX * startPadding);
        int trimmedStartY = (int) Math.round(start.getY() + unitY * startPadding);
        int trimmedEndX = (int) Math.round(end.getX() - unitX * endPadding);
        int trimmedEndY = (int) Math.round(end.getY() - unitY * endPadding);

        graphics.drawLine(trimmedStartX, trimmedStartY, trimmedEndX, trimmedEndY);
    }

    private int clamp(int value, int min, int max) {
        return Math.max(min, Math.min(max, value));
    }

    private String normalizePlayerName(String name) {
        return name.toLowerCase().trim();
    }

    private static final class RenderedHighlight {
        private final Player player;
        private final HighlightStyle style;
        private long fadeStartTime = -1L;

        private RenderedHighlight(Player player, HighlightStyle style) {
            this.player = player;
            this.style = style;
        }

        private Player getPlayer() {
            return player;
        }

        private HighlightStyle getStyle() {
            return style;
        }

        private void startFade(long now) {
            fadeStartTime = now;
        }

        private float getFadeAlpha(long now, int fadeDurationMs) {
            if (fadeStartTime < 0L) {
                return 1.0f;
            }

            long elapsed = now - fadeStartTime;
            if (elapsed >= fadeDurationMs) {
                return 0.0f;
            }

            return 1.0f - (float) elapsed / fadeDurationMs;
        }
    }
}

